1	import React, { type CSSProperties } from 'react';
2	import {
3	  Button as ChakraButton,
4	  IconButton,
5	  VisuallyHidden,
6	  chakra,
7	  useStyleConfig,
8	  useMultiStyleConfig,
9	  type SystemStyleObject,
10	} from '@chakra-ui/react';
11	import { ZimmIcon } from '../zimmIcon';
12	import type { ZimmIconType, ZimmIconSize } from '../zimmIcon';
13	
14	// All hover/press/focus/disabled interaction states live in zimmButton.css.ts, co-located
15	// beside this file. ZimmButton is a thin mapping layer: Zimmermann props (inverse,
16	// large/medium) → Chakra variant/size names that zimmButton.css.ts recognises.
17	
18	type ZimmButtonBaseProps = {
19	  /** Visible label (primary/secondary) or aria-label (icon variant — no visible text). */
20	  label: string;
21	  type?: 'button' | 'submit' | 'reset';
22	  disabled?: boolean;
23	  /**
24	   * Renders the disabled *appearance* while keeping the button focusable and in the Tab
25	   * order (A10) — HTML `disabled` removes it from the accessibility tree entirely, so screen
26	   * reader users can never reach it to hear why the action is unavailable. `onClick` is
