const BASE = 'http://localhost:6006/iframe.html';
const STORIES = {
  default: 'commerce-zimmcartbuttongroup--default',
  international: 'commerce-zimmcartbuttongroup--international',
  errorInCart: 'commerce-zimmcartbuttongroup--error-in-cart',
};
const SCRATCH = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/6017b702-06fb-4295-9164-1c708495531a/scratchpad';

function storyUrl(id) {
  return `${BASE}?id=${id}&viewMode=story`;
}

let ROOT_SELECTOR = '#storybook-root';

async function gotoStory(page, id, label) {
  const target = storyUrl(id);
  console.log(`\n--- Navigating to ${label}: ${target} ---`);
  await page.goto(target, { waitUntil: 'load', timeout: 30000 });
  try {
    await page.waitForLoadState('networkidle', { timeout: 8000 });
    console.log('  networkidle reached');
  } catch (e) {
    console.log(`  networkidle did not settle within 8s, continuing anyway (${e.message})`);
  }
  try {
    await page.waitForSelector(ROOT_SELECTOR, { timeout: 10000 });
  } catch (e) {
    console.log(`  ${ROOT_SELECTOR} not found within 10s, trying #root as fallback`);
    ROOT_SELECTOR = '#root';
    await page.waitForSelector(ROOT_SELECTOR, { timeout: 10000 });
  }
  await page.waitForTimeout(500);
}

async function checkErrorBoundary(page) {
  return page.evaluate(() => {
    const bodyText = document.body.innerText || '';
    const errorSignatures = [
      'Something went wrong',
      'error boundary',
      "Cannot read propert",
      'is not a function',
      'Uncaught',
      'ChunkLoadError',
      'Story rendering error',
      'The component threw an error',
      'render is not a function',
    ];
    const matched = errorSignatures.filter((s) => bodyText.toLowerCase().includes(s.toLowerCase()));
    const errorMessageEl = document.querySelector('#error-message');
    const sbErrorDisplay = document.querySelector('.sb-errordisplay');
    return {
      bodyTextSnippet: bodyText.slice(0, 300),
      matchedErrorSignatures: matched,
      hasErrorMessageEl: !!errorMessageEl,
      errorMessageElText: errorMessageEl ? errorMessageEl.innerText.slice(0, 300) : null,
      hasSbErrorDisplay: !!sbErrorDisplay,
    };
  });
}

async function countButtons(page) {
  return page.$$eval(`${ROOT_SELECTOR} button`, (els) => els.length);
}

(async () => {
