    console.log(`  ${ROOT_SELECTOR} not found within 10s, trying #root as fallback`);
    ROOT_SELECTOR = '#root';
    await page.waitForSelector(ROOT_SELECTOR, { timeout: 10000 });
  }
  await page.waitForTimeout(500);
