const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto('http://localhost:6006/iframe.html?id=commerce-zimmcartbuttongroup--default&viewMode=story', { waitUntil: 'load', timeout: 30000 });
  await page.waitForSelector('#storybook-root button', { timeout: 15000 });
  await page.waitForTimeout(800);

  const dump = await page.evaluate(() => {
    const btn = Array.from(document.querySelectorAll('#storybook-root button')).find(
      (b) => b.getAttribute('aria-label') === 'Apple Pay'
    );
    const fullHTML = btn.outerHTML;
    const allEls = Array.from(btn.querySelectorAll('*'));
    const absoluteEls = allEls
      .filter((el) => getComputedStyle(el).position === 'absolute')
      .map((el) => ({ tag: el.tagName, className: el.className, text: (el.textContent || '').trim().slice(0, 40), rect: el.getBoundingClientRect().toJSON ? el.getBoundingClientRect().toJSON() : el.getBoundingClientRect() }));
    const textMatches = allEls
      .filter((el) => (el.textContent || '').includes('Apple Pay'))
      .map((el) => ({ tag: el.tagName, className: el.className, childrenCount: el.children.length, ownText: Array.from(el.childNodes).filter(n=>n.nodeType===3).map(n=>n.textContent).join('|') }));
    return { fullHTML, absoluteEls, textMatches, htmlLength: fullHTML.length };
  });
  console.log('FULL HTML LENGTH:', dump.htmlLength);
  console.log('FULL HTML:\n', dump.fullHTML);
  console.log('\nABSOLUTE-POSITIONED DESCENDANTS:\n', JSON.stringify(dump.absoluteEls, null, 2));
  console.log('\nELEMENTS WHOSE textContent INCLUDES "Apple Pay":\n', JSON.stringify(dump.textMatches, null, 2));

  // also check chakra/emotion CSS actually loaded - look for style tags
  const styleTagCount = await page.evaluate(() => document.querySelectorAll('style').length);
  console.log('\n<style> tag count on page:', styleTagCount);

  // check the button's label span class against emotion-generated css rule content
  const labelSpanClass = await page.evaluate(() => {
    const btn = Array.from(document.querySelectorAll('#storybook-root button')).find(b => b.getAttribute('aria-label') === 'Apple Pay');
    const leaf = Array.from(btn.querySelectorAll('*')).find(el => el.children.length === 0 && (el.textContent||'').trim() === 'Apple Pay');
    return leaf ? { className: leaf.className, outerHTML: leaf.outerHTML } : null;
  });
  console.log('\nLabel leaf span:', JSON.stringify(labelSpanClass, null, 2));

  // search all style tags for that class's rule
  if (labelSpanClass && labelSpanClass.className) {
    const cls = labelSpanClass.className.split(' ').find(c => c.startsWith('css-'));
    const ruleText = await page.evaluate((cls) => {
      const sheets = Array.from(document.styleSheets);
      let found = [];
      for (const sheet of sheets) {
        let rules;
        try { rules = Array.from(sheet.cssRules || []); } catch (e) { continue; }
        for (const r of rules) {
          if (r.selectorText && r.selectorText.includes(cls)) {
            found.push(r.cssText);
          }
        }
      }
      return found;
    }, cls);
    console.log(`\nCSS rules matching class .${cls}:\n`, JSON.stringify(ruleText, null, 2));
  }

  await browser.close();
})().catch(e => { console.error('ERROR', e); process.exit(1); });
EOF
