const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

function measure(page) {
  return page.evaluate(() => {
    const btn = Array.from(document.querySelectorAll('#storybook-root button')).find(
      (b) => b.getAttribute('aria-label') === 'Apple Pay'
    );
    if (!btn) return { error: 'button not found' };
    const leaf = Array.from(btn.querySelectorAll('*')).find(
      (el) => el.children.length === 0 && (el.textContent || '').trim() === 'Apple Pay'
    );
    if (!leaf) return { error: 'leaf not found', outerHTML: btn.outerHTML.slice(0, 300) };
    const cs = getComputedStyle(leaf);
    const rect = leaf.getBoundingClientRect();
    return {
      className: leaf.className,
      position: cs.position,
      width: cs.width,
      height: cs.height,
      overflow: cs.overflow,
      clip: cs.clip,
      rectWidth: rect.width,
      rectHeight: rect.height,
      styleTagCount: document.querySelectorAll('style').length,
    };
  });
}

(async () => {
  // Test A: fresh browser, fresh page, single navigation, sample at multiple times
  console.log('=== TEST A: single fresh navigation, sampled over time ===');
  const browserA = await chromium.launch({ headless: true });
  const pageA = await browserA.newPage({ viewport: { width: 1280, height: 900 } });
  const t0 = Date.now();
  await pageA.goto('http://localhost:6006/iframe.html?id=commerce-zimmcartbuttongroup--default&viewMode=story', { waitUntil: 'load', timeout: 30000 });
  await pageA.waitForSelector('#storybook-root button', { timeout: 15000 });
  console.log(`DOM button appeared at +${Date.now() - t0}ms`);
  for (const delay of [0, 100, 300, 500, 1000, 2000, 3000]) {
    if (delay > 0) await pageA.waitForTimeout(delay - (delay === 0 ? 0 : 0));
    const m = await measure(pageA);
    console.log(`  sample at ~+${Date.now()-t0}ms (requested delay ${delay}ms):`, JSON.stringify(m));
  }
  await browserA.close();

  // Test B: repeat the ENTIRE original script's navigation pattern (many sequential gotos on one page)
  // to see if repeated navigation on a long-lived page reproduces the "static/visible" reading.
  console.log('\n=== TEST B: many sequential gotos on ONE page/context, like the original script, then measure ===');
  const browserB = await chromium.launch({ headless: true });
  const pageB = await browserB.newPage({ viewport: { width: 1280, height: 900 } });
  const urls = [
    'commerce-zimmcartbuttongroup--default',
    'commerce-zimmcartbuttongroup--international',
    'commerce-zimmcartbuttongroup--error-in-cart',
    'commerce-zimmcartbuttongroup--default',
    'commerce-zimmcartbuttongroup--international',
    'commerce-zimmcartbuttongroup--default',
    'commerce-zimmcartbuttongroup--international',
    'commerce-zimmcartbuttongroup--default',
  ];
  for (const id of urls) {
    await pageB.goto(`http://localhost:6006/iframe.html?id=${id}&viewMode=story`, { waitUntil: 'load', timeout: 30000 });
    try { await pageB.waitForLoadState('networkidle', { timeout: 8000 }); } catch (e) {}
    await pageB.waitForSelector('#storybook-root', { timeout: 10000 });
    await pageB.waitForTimeout(500);
  }
  const mB = await measure(pageB);
  console.log('Final measurement after repeated navigation (500ms wait, same as original script):', JSON.stringify(mB));
  await pageB.waitForTimeout(2000);
  const mB2 = await measure(pageB);
  console.log('Same page, +2000ms more wait:', JSON.stringify(mB2));
  await browserB.close();

  // Test C: exactly replicate original script's per-story wait pattern used in TASK2, i.e. immediately
  // after the SAME sequence used originally (default, international, error-in-cart, then back to default for task2)
  console.log('\n=== TEST C: exact original TASK1->TASK2 sequence replicated ===');
  const browserC = await chromium.launch({ headless: true });
  const pageC = await browserC.newPage({ viewport: { width: 1280, height: 900 } });
  async function gotoLikeOriginal(page, id) {
    await page.goto(`http://localhost:6006/iframe.html?id=${id}&viewMode=story`, { waitUntil: 'load', timeout: 30000 });
    try { await page.waitForLoadState('networkidle', { timeout: 8000 }); } catch (e) {}
    await page.waitForSelector('#storybook-root', { timeout: 10000 });
    await page.waitForTimeout(500);
  }
  await gotoLikeOriginal(pageC, 'commerce-zimmcartbuttongroup--default');
  await gotoLikeOriginal(pageC, 'commerce-zimmcartbuttongroup--international');
  await gotoLikeOriginal(pageC, 'commerce-zimmcartbuttongroup--error-in-cart');
  await gotoLikeOriginal(pageC, 'commerce-zimmcartbuttongroup--default'); // this is the TASK2 nav
  const mC = await measure(pageC);
  console.log('Measurement immediately (matches original TASK2 timing exactly):', JSON.stringify(mC));
  await browserC.close();
})().catch(e => { console.error('ERROR', e); process.exit(1); });
EOF
