const fs = require('fs');
const path = require('path');
const { chromium } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/playwright');

const BASE = 'http://localhost:6006/iframe.html';
const STORIES = {
  default: 'commerce-zimmcartbuttongroup--default',
  international: 'commerce-zimmcartbuttongroup--international',
  errorInCart: 'commerce-zimmcartbuttongroup--error-in-cart',
};
const SCRATCH = '/private/tmp/claude-501/-Users-marcel-a-n-navarro-Dev-zimmermann-pwa/6017b702-06fb-4295-9164-1c708495531a/scratchpad';
const ROOT = '#storybook-root';

function storyUrl(id) { return `${BASE}?id=${id}&viewMode=story`; }

async function freshPage(browser) {
  const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const page = await ctx.newPage();
  return { ctx, page };
}

async function load(page, id) {
  await page.goto(storyUrl(id), { waitUntil: 'load', timeout: 30000 });
  await page.waitForSelector(`${ROOT} button`, { timeout: 15000 });
  await page.waitForTimeout(1200); // generous settle time, isolated fresh page every time
}

(async () => {
  const report = {};
  const browser = await chromium.launch({ headless: true });

  // TASK 1 + 3 combined: counts + error-boundary check + international accessible-name check, fresh page each
  report.task1 = {};
  for (const [key, id] of Object.entries(STORIES)) {
    const { ctx, page } = await freshPage(browser);
    await load(page, id);
    const count = await page.$$eval(`${ROOT} button`, els => els.length);
    const errInfo = await page.evaluate(() => {
      const bodyText = document.body.innerText || '';
      const sigs = ['Something went wrong','error boundary','Cannot read propert','is not a function','Uncaught','ChunkLoadError'];
      return {
        bodyTextSnippet: bodyText.slice(0, 200),
        matchedErrorSignatures: sigs.filter(s => bodyText.toLowerCase().includes(s.toLowerCase())),
      };
    });
    report.task1[key] = { count, errInfo };
    console.log(`[TASK1] ${key}: count=${count} errSigs=${JSON.stringify(errInfo.matchedErrorSignatures)} text="${errInfo.bodyTextSnippet}"`);
    await ctx.close();
  }

  // TASK 3 explicit re-check on fresh page
  {
    const { ctx, page } = await freshPage(browser);
    await load(page, STORIES.international);
    const applePayByRole = await page.getByRole('button', { name: /apple pay/i }).count();
    const googlePayByRole = await page.getByRole('button', { name: /google pay/i }).count();
    const domCheck = await page.evaluate(() => {
      const all = Array.from(document.querySelectorAll('body *'));
      const ariaMatches = all.filter(el => { const al = el.getAttribute && el.getAttribute('aria-label'); return al && /apple pay|google pay/i.test(al); }).length;
      const textMatches = all.filter(el => el.children.length === 0 && /apple pay|google pay/i.test((el.textContent||'').trim())).length;
      return { ariaMatches, textMatches };
    });
    report.task3 = { applePayByRole, googlePayByRole, domCheck };
    console.log('[TASK3]', JSON.stringify(report.task3));
    await ctx.close();
  }

  // TASK 2: definitive label-clipping check, fresh page, generous wait, all 3 buttons
  {
    const { ctx, page } = await freshPage(browser);
    await load(page, STORIES.default);
    const task2 = await page.evaluate(() => {
      function leafFor(btn, expectedText) {
        return Array.from(btn.querySelectorAll('*')).find(
          el => el.children.length === 0 && (el.textContent || '').trim() === expectedText
        );
      }
      function describe(el) {
        if (!el) return null;
        const cs = getComputedStyle(el);
        const rect = el.getBoundingClientRect();
        return {
          className: el.className,
          position: cs.position,
          width: cs.width,
          height: cs.height,
          overflow: cs.overflow,
          clip: cs.clip,
          clipPath: cs.clipPath,
          margin: cs.margin,
          rectWidth: rect.width,
          rectHeight: rect.height,
        };
      }
      const buttons = Array.from(document.querySelectorAll('#storybook-root button'));
      const checkout = buttons.find(b => b.getAttribute('aria-label') === 'Checkout');
      const apple = buttons.find(b => b.getAttribute('aria-label') === 'Apple Pay');
      const google = buttons.find(b => b.getAttribute('aria-label') === 'Google Pay');
      return {
        checkoutLabel: describe(leafFor(checkout, 'Checkout')),
        applePayLabel: describe(leafFor(apple, 'Apple Pay')),
        googlePayLabel: describe(leafFor(google, 'Google Pay')),
      };
    });
    report.task2 = task2;
    console.log('[TASK2] final clean measurement:\n' + JSON.stringify(task2, null, 2));
    await page.screenshot({ path: path.join(SCRATCH, 'default-story-final.png'), fullPage: true });
    console.log('[TASK2] screenshot: default-story-final.png');
    await ctx.close();
  }

  // TASK 4: heights, fresh pages
  {
    const { ctx, page } = await freshPage(browser);
    await load(page, STORIES.default);
    const t4d = await page.evaluate(() => {
      const buttons = Array.from(document.querySelectorAll('#storybook-root button'));
      const container = buttons[0].parentElement;
      const sameParent = buttons.every(b => b.parentElement === container);
      const cr = container.getBoundingClientRect();
      const cs = getComputedStyle(container);
      return {
        sameParent,
        containerHeight: cr.height,
        containerGap: cs.gap,
        buttonHeights: buttons.map(b => ({ label: b.getAttribute('aria-label'), height: b.getBoundingClientRect().height })),
      };
    });
    report.task4Default = t4d;
    console.log('[TASK4] default:', JSON.stringify(t4d));
    await ctx.close();
  }
  {
    const { ctx, page } = await freshPage(browser);
    await load(page, STORIES.international);
    const t4i = await page.evaluate(() => {
      const buttons = Array.from(document.querySelectorAll('#storybook-root button'));
      const container = buttons[0].parentElement;
      const cr = container.getBoundingClientRect();
      const cs = getComputedStyle(container);
      return {
        containerHeight: cr.height,
        containerGap: cs.gap,
        buttonHeights: buttons.map(b => ({ label: b.getAttribute('aria-label'), height: b.getBoundingClientRect().height })),
      };
    });
    report.task4International = t4i;
    console.log('[TASK4] international:', JSON.stringify(t4i));
    await ctx.close();
  }
  if (report.task4Default && report.task4International) {
    const avgH = report.task4Default.buttonHeights.reduce((a,b)=>a+b.height,0) / report.task4Default.buttonHeights.length;
    const gap = parseFloat(report.task4Default.containerGap) || 16;
    const predicted = report.task4Default.containerHeight - 2*avgH - 2*gap;
    const actual = report.task4International.containerHeight;
    report.task4Arithmetic = { avgSingleButtonHeight: avgH, gapPx: gap, predictedInternationalHeight: predicted, actualInternationalHeight: actual, diff: actual - predicted };
    console.log('[TASK4] arithmetic:', JSON.stringify(report.task4Arithmetic));
  }

  // TASK 5 + 6: svg measurements, fresh page
  {
    const { ctx, page } = await freshPage(browser);
    await load(page, STORIES.default);
    const t56 = await page.evaluate(() => {
      function getBtn(label) { return Array.from(document.querySelectorAll('#storybook-root button')).find(b => b.getAttribute('aria-label') === label); }
      const out = {};
      for (const [name, label] of [['applePay','Apple Pay'], ['googlePay','Google Pay']]) {
        const btn = getBtn(label);
        const svg = btn.querySelector('svg');
        const btnRect = btn.getBoundingClientRect();
        const svgRect = svg.getBoundingClientRect();
        out[name] = {
          btnTop: btnRect.top, btnHeight: btnRect.height,
          svgTop: svgRect.top, svgLeft: svgRect.left, svgWidth: svgRect.width, svgHeight: svgRect.height,
          viewBox: svg.getAttribute('viewBox'),
        };
      }
      return out;
    });
    report.task56 = t56;
    const appleRatio = t56.applePay.svgWidth / t56.applePay.svgHeight;
    const googleRatio = t56.googlePay.svgWidth / t56.googlePay.svgHeight;
    const appleCentre = (t56.applePay.svgTop - t56.applePay.btnTop) + t56.applePay.svgHeight/2;
    const googleCentre = (t56.googlePay.svgTop - t56.googlePay.btnTop) + t56.googlePay.svgHeight/2;
    report.task5Ratios = { appleRatio, googleRatio };
    report.task6Centres = { appleCentre, googleCentre, diff: appleCentre - googleCentre };
    console.log('[TASK5-6] raw:', JSON.stringify(t56));
    console.log('[TASK5] ratios:', JSON.stringify(report.task5Ratios));
    console.log('[TASK6] centres:', JSON.stringify(report.task6Centres));
    await ctx.close();
  }

  // TASK 7: focus states, fresh page
  {
    const { ctx, page } = await freshPage(browser);
    await load(page, STORIES.default);
    const resting = await page.evaluate(() => {
      const buttons = Array.from(document.querySelectorAll('#storybook-root button'));
      const out = {};
      buttons.forEach(b => { const cs = getComputedStyle(b); out[b.getAttribute('aria-label')] = { outline: cs.outline, outlineColor: cs.outlineColor, boxShadow: cs.boxShadow }; });
      return out;
    });
    await page.evaluate(() => { if (document.activeElement && document.activeElement.blur) document.activeElement.blur(); });
    const focusLog = [];
    const expected = ['Checkout','Apple Pay','Google Pay'];
    const seen = new Set();
    for (let i = 0; i < 10 && seen.size < 3; i++) {
      await page.keyboard.press('Tab');
      const info = await page.evaluate(() => {
        const el = document.activeElement;
        if (!el) return null;
        const cs = getComputedStyle(el);
        return { ariaLabel: el.getAttribute && el.getAttribute('aria-label'), outline: cs.outline, outlineColor: cs.outlineColor, boxShadow: cs.boxShadow };
      });
      focusLog.push(info);
      if (info && expected.includes(info.ariaLabel) && !seen.has(info.ariaLabel)) {
        seen.add(info.ariaLabel);
        await page.screenshot({ path: path.join(SCRATCH, `focus-final-${info.ariaLabel.replace(/\s+/g,'-').toLowerCase()}.png`) });
      }
    }
    report.task7 = { resting, focusLog, distinctFocused: Array.from(seen) };
    console.log('[TASK7] resting:', JSON.stringify(resting));
    console.log('[TASK7] focusLog:', JSON.stringify(focusLog));
    await ctx.close();
  }

  await browser.close();
  fs.writeFileSync(path.join(SCRATCH, 'final-report.json'), JSON.stringify(report, null, 2));
  console.log('\n=== FINAL REPORT WRITTEN ===');
})().catch(e => { console.error('SCRIPT ERROR', e); process.exit(1); });
